    def policy_mapping(self):
        self.set_scores(
            PolicyScores(
                ExplorationScore(
                    [self.float_range(-4.0, 4.0, group="scores") for _ in range(5)],
                    centers=[0.0] * 5,
                    pow=1,
                ),
                FinalizationScore(
                    [self.float_range(-4.0, 4.0, group="scores") for _ in range(6)],
                    centers=[0.0] * 6,
                    pow=1,
                ),
            )
        )
        scout_policy = self._scout_policy()
        tail_policy = self._tail_policy()
        selection, pool, tohpe, todd = tail_policy if self.tail_mode else scout_policy
        self.set_action_selection(selection)
        self.set_action_pool(pool)
        self.set_tohpe_search(tohpe)
        self.set_todd_search(todd)

    def _scout_policy(self):
        return (
            ActionSelection(beamwidth=2, mode="softmax", temperature=0.26),
            ActionPool(final_size=self.int_range(12, 28, group="scout")),
            TohpeSearch(
                SamplingBudget(one_hot="all", sparse=0, dense=8, sparse_max_weight=2),
                SourcePool(
                    keep=self.int_range(10, 28, group="scout"),
                    reserve=self.int_range(1, 6, group="scout"),
                ),
                z_choices=self.int_range(4, 16, group="scout"),
            ),
            ToddSearch(
                SamplingBudget(one_hot=0, sparse=0, dense=0, sparse_max_weight=0),
                SourcePool(keep=0, reserve=0),
                actions_per_bucket=0,
                buckets=ZBucketSearch(min_buckets=0, max_buckets=0, limit_bucket=0),
            ),
        )

    def _tail_policy(self):
        cap = max(256, round(self.buckets_space * 0.08))
        return (
            ActionSelection(
                beamwidth=self.int_range(2, 3, group="tail"),
                mode="softmax",
                temperature=0.16,
            ),
            ActionPool(final_size=self.int_range(24, 48, group="tail")),
            TohpeSearch(
                SamplingBudget(one_hot="all", sparse=6, dense=10, sparse_max_weight=3),
                SourcePool(keep=10, reserve=2),
                z_choices=6,
            ),
            ToddSearch(
                SamplingBudget(one_hot="all", sparse=8, dense=8, sparse_max_weight=3),
                SourcePool(
                    keep=self.int_range(5, 12, group="tail"),
                    reserve=self.int_range(1, 3, group="tail"),
                ),
                actions_per_bucket=self.int_range(2, 4, group="tail"),
                buckets=ZBucketSearch(
                    min_buckets=max(64, cap // 20),
                    max_buckets=cap,
                    limit_bucket=cap,
                ),
            ),
        )

    def __call__(self, params: Iterable[float]) -> float:
        return float(min(self.run(params, SEARCH_SEEDS)))


class Problem(ElementwiseProblem):
    def __init__(self, evaluator: Evaluator):
        size = len(evaluator.extract_active())
        super().__init__(n_var=size, n_obj=1, xl=np.full(size, -1.0), xu=np.full(size, 1.0))
        self.evaluator = evaluator

    def _evaluate(self, x, out, *args, **kwargs):
        out["F"] = self.evaluator(np.asarray(x, dtype=float))


def optimize(evaluator: Evaluator, algorithm, evaluations: int, seed: int) -> np.ndarray:
    current = evaluator.extract_active()
    result = minimize(
        Problem(evaluator), algorithm, termination=("n_eval", evaluations), seed=seed, verbose=False
    )
    return np.asarray(result.X if result.X is not None else current, dtype=float)


def entrypoint():
    evaluator = Evaluator(path_name="init", margin=MARGIN, max_depth=MAX_DEPTH)
    evaluator.select_parameter_groups("scores", "scout")
    params = optimize(
        evaluator,
        PSO(pop_size=10, w=0.72, c1=0.9, c2=0.9, adaptive=False),
        SCOUT_EVALS,
        seed=31,
    )
    evaluator.tail_mode = True
    restarted = evaluator.set_up_new_init(
        0, rank_thr=evaluator.best_rank + REOPEN_MARGIN, xopt=params
    )
    if restarted is not None:
        evaluator.select_parameter_groups("scores", "tail")
        optimize(
            evaluator,
            PatternSearch(x0=np.clip(evaluator.extract_active(), -1.0, 1.0), init_delta=0.25),
            TAIL_EVALS,
            seed=32,
        )
    return evaluator.get_best()


AUX_DESCRIPTION = """
Pool role: the moderate heavy-tail specialist. Cheap TOHPE discovers a path;
only its reopened tail receives substantial matrix-scaled TODD coverage and a
small beam increase, preserving the majority of useful expensive evaluations.
"""

"""Near-end refinement: fix terminal pool underfill with positive scores, capped TODD z, and DE optimizer."""

from collections.abc import Iterable

from helper import (
    INITIAL_RANK,
    TARGET_FINAL_RANK,
    ActionPool,
    ActionSelection,
    BaseEvaluator,
    ExplorationScore,
    FinalizationScore,
    PolicyScores,
    SamplingBudget,
    SourcePool,
    ToddSearch,
    TohpeSearch,
    ZBucketSearch,
)
import numpy as np
from pymoo.algorithms.soo.nonconvex.de import DE
from pymoo.core.problem import ElementwiseProblem
from pymoo.optimize import minimize


OPTIMIZER_FAMILY = "pymoo_de_terminal_fix_pool_and_scores"
SEARCH_SEEDS = (37, 41)
SCOUT_EVALS = 80
TAIL_EVALS = 240
TARGET_TOTAL_EVALS = 320
RANK_SPAN = max(1, INITIAL_RANK - TARGET_FINAL_RANK)
MARGIN = 35
REOPEN_MARGIN = max(5, round(0.12 * RANK_SPAN))
MAX_DEPTH = max(500, RANK_SPAN + 64)


def disabled_todd() -> ToddSearch:
    return ToddSearch(
        SamplingBudget(one_hot=0, sparse=0, dense=0, sparse_max_weight=0),
        SourcePool(keep=0, reserve=0),
        actions_per_bucket=0,
        buckets=ZBucketSearch(min_buckets=0, max_buckets=0, limit_bucket=0),
    )


class Evaluator(BaseEvaluator):
    def __init__(self, *args, **kwargs):
        self.tail_mode = False
        super().__init__(*args, **kwargs)

    def float_range(self, low: float, high: float, *, group: str) -> float:
        return self.map_par(
            lambda x: low + (high - low) / (1.0 + np.exp(-float(x))), group=group
        )

    def int_range(self, low: int, high: int, *, group: str) -> int:
        return self.map_par(
            lambda x: min(high, low + int((high - low + 1) / (1.0 + np.exp(-float(x))))),
            group=group,
        )

    def policy_mapping(self):
        # Fix score_center_mismatch: positive-only exploration weights reward
        # higher reduction and dimension during source pooling. All centers at
        # zero so higher features always get higher scores.
        self.set_scores(
            PolicyScores(
                ExplorationScore(
                    [self.float_range(0.0, 4.0, group="scores") for _ in range(5)],
                    centers=[0.0] * 5,
                    pow=1,
                ),
                FinalizationScore(
                    [self.float_range(0.0, 4.0, group="scores") for _ in range(6)],
                    centers=[0.0] * 6,
                    pow=1,
                ),
            )
        )
        if self.tail_mode:
            self.set_tohpe_search(self._tail_tohpe())
            self.set_todd_search(self._tail_todd())
            # High beamwidth (6) to traverse the richer merged pool.
            # Moderate temperature (0.30) for softmax diversity.
            self.set_action_selection(
                ActionSelection(beamwidth=6, mode="softmax", temperature=0.30)
            )
            self.set_action_pool(
                ActionPool(final_size=self.int_range(40, 64, group="tail"))
            )
        else:
            self.set_tohpe_search(self._scout_tohpe())
            self.set_todd_search(disabled_todd())
            self.set_action_selection(
                ActionSelection(beamwidth=1, mode="softmax", temperature=0.30)
            )
            self.set_action_pool(
                ActionPool(final_size=self.int_range(12, 24, group="scout"))
            )

    def _scout_tohpe(self):
        return TohpeSearch(
            SamplingBudget(one_hot="all", sparse=0, dense=6, sparse_max_weight=2),
            SourcePool(
                keep=self.int_range(12, 20, group="scout"),
                reserve=self.int_range(2, 5, group="scout"),
            ),
            z_choices=self.int_range(6, 14, group="scout"),
        )

    def _tail_tohpe(self):
        # Terminal dim 2-3: nonzero y-space has only 3-7 vectors.
        # one_hot='all' enumerates every weight-1 vector; additional
        # sparse/dense y samples are pure waste — remove them entirely.
        return TohpeSearch(
            SamplingBudget(one_hot="all", sparse=0, dense=0, sparse_max_weight=0),
            SourcePool(
                keep=self.int_range(12, 20, group="tail"),
                reserve=4,
            ),
            z_choices=self.int_range(8, 16, group="tail"),
        )

    def _tail_todd(self):
        # Fix terminal action starvation: high keep/reserve ensures discovered
        # TODD actions survive merging into the final pool. Cap z research
        # with max_buckets=1000 to avoid runtime blowout from unlimited
        # bucket searching while preserving guaranteed coverage via min_buckets.
        return ToddSearch(
            SamplingBudget(one_hot=6, sparse=4, dense=4, sparse_max_weight=2),
            SourcePool(
                keep=self.int_range(20, 30, group="tail"),
                reserve=self.int_range(8, 12, group="tail"),
            ),
            actions_per_bucket=self.int_range(6, 8, group="tail"),
            buckets=ZBucketSearch(
                min_buckets=max(10, round(self.buckets_space * 0.005)),
                max_buckets=1000,
                limit_bucket=-1,
            ),
        )

    def __call__(self, params: Iterable[float]) -> float:
        return float(min(self.run(params, SEARCH_SEEDS)))


class Problem(ElementwiseProblem):
    def __init__(self, evaluator: Evaluator):
        size = len(evaluator.extract_active())
        super().__init__(n_var=size, n_obj=1, xl=np.full(size, -1.0), xu=np.full(size, 1.0))
        self.evaluator = evaluator

    def _evaluate(self, x, out, *args, **kwargs):
        out["F"] = self.evaluator(np.asarray(x, dtype=float))


def optimize(evaluator: Evaluator, evaluations: int, seed: int) -> np.ndarray:
    current = evaluator.extract_active()
    result = minimize(
        Problem(evaluator),
        DE(pop_size=12, variant="DE/rand/1/bin", CR=0.9, F=0.8),
        termination=("n_eval", evaluations),
        seed=seed,
        verbose=False,
    )
    return np.asarray(result.X if result.X is not None else current, dtype=float)


def entrypoint():
    # Load f1201_i1384 with higher init_rank (1384) for a less-saturated
    # terminal suffix compared to lower-init_rank paths at same rank 1201.
    evaluator = Evaluator(
        path_name="f1201_i1384_08810e12_z2157of3193",
        margin=MARGIN,
        max_depth=MAX_DEPTH,
    )
    evaluator.select_parameter_groups("scores", "scout")
    params = optimize(evaluator, SCOUT_EVALS, seed=37)
    evaluator.tail_mode = True
    restarted = evaluator.set_up_new_init(
        0, rank_thr=evaluator.best_rank + REOPEN_MARGIN, xopt=params
    )
    if restarted is not None:
        evaluator.select_parameter_groups("scores", "tail")
        optimize(evaluator, TAIL_EVALS, seed=41)
    return evaluator.get_best()

